        data: {"result": {"minY": 45.0, "minX": 0.0, "maxY": 9931.0, "series": [{"data": [[0.0, 4632.0], [600.0, 57.0], [300.0, 45.0], [700.0, 49.0], [400.0, 50.0], [200.0, 60.0], [100.0, 57.0], [500.0, 50.0]], "isOverall": false, "label": "POST start async catalog report", "isController": false}, {"data": [[0.0, 9931.0], [100.0, 69.0]], "isOverall": false, "label": "GET async job status", "isController": false}], "supportsControllersDiscrimination": true, "granularity": 100, "maxX": 700.0, "title": "Response Time Distribution"}},
